import itertools

def calculate_P(edges):
    degrees = {}
    for u, v in edges:
        degrees[u] = degrees.get(u, 0) + 1
        degrees[v] = degrees.get(v, 0) + 1
    P = 0
    for u, v in edges:
        P += min(degrees[u], degrees[v])
    return P

def solve_small(n):
    max_P = 0
    # k is the number of vertices.
    # Smallest k such that k(k-1)/2 >= n
    import math
    k_min = math.ceil((1 + math.sqrt(1 + 8 * n)) / 2)

    # For small n, we can try k up to n+1.
    for k in range(k_min, n + 2):
        # All possible edges among k vertices
        edges_list = list(itertools.combinations(range(k), 2))
        # All possible subsets of edges of size n
        for edges in itertools.combinations(edges_list, n):
            max_P = max(max_P, calculate_P(edges))
    return max_P

for n in range(1, 16):
    print(f"n={n}, max_P={solve_small(n)}")
